{
  "name": "artifact-tools",
  "description": "Reads and writes an artifact by the part it needs (a frontmatter field or a level-2 section), renders a parent's children and what references an artifact fresh from the corpus on every call, and fills a scenario's `@hash:` and a bead's initiative from what the corpus already states. Use it instead of loading or quoting a whole artifact, and wherever a calculated field or a filled value would otherwise be typed by hand.",
  "uses": [
    {
      "name": "read",
      "description": "Returns the text of one named part of an artifact \u2014 a frontmatter field or a level-2 section \u2014 and nothing else: the artifact's other sections and its history are left out unless that part is the one asked for.",
      "invocation": "python3 basis/tools/artifact_tools.py read <path> --section <section>",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "the artifact's path, repository-relative or absolute"
          },
          "section": {
            "type": "string",
            "description": "the frontmatter field name, or the section's heading (a step's name before ` \u2014 `, where its heading carries one)"
          }
        },
        "required": [
          "path",
          "section"
        ],
        "additionalProperties": false
      },
      "returns": {
        "form": "text",
        "text": "the named part's text on standard output, unmodified; exit status 0"
      },
      "failures": [
        {
          "code": "unreadable",
          "exit_status": 2,
          "condition": "the path does not exist, or names no frontmatter field or section matching <section>; one line on standard error beginning `unreadable:` names the artifact, the section asked for, and the section and field names that do exist; nothing is returned",
          "next": "give an existing path and one of the names listed, then run again"
        },
        {
          "code": "usage",
          "exit_status": 2,
          "condition": "the arguments are not one of the six invocations this tool states \u2014 no path, a missing required flag, an unknown flag, or a flag without its value; one line on standard error beginning `usage:` names the invocations; nothing is read or written",
          "next": "run the invocation the use states, as written"
        }
      ]
    },
    {
      "name": "write",
      "description": "Replaces one existing part's text \u2014 a frontmatter field or a level-2 section's body \u2014 with the given content, in place; every other part of the artifact is left unchanged and unread by the caller.",
      "invocation": "python3 basis/tools/artifact_tools.py write <path> --part <part> --content <content>",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "the artifact's path, repository-relative or absolute"
          },
          "part": {
            "type": "string",
            "description": "the frontmatter field name, or the section's heading key, to replace"
          },

