{
 "name": "fill-hash",
 "description": "Computes a scenario's `@hash:` \u2014 sha256 of its `Scenario:`/`Given`/`When`/`Then` (and `And`/`But`) lines, trimmed and newline-joined, first twelve hex digits \u2014 and writes it onto the scenario's tag line; the caller never supplies the hash.",
 "invocation": "python3 basis/tools/artifact_tools.py fill-hash <feature> --scenario <name>",
 "input_schema": {
  "type": "object",
  "properties": {
   "feature": {
    "type": "string",
    "description": "the feature file's path"
   },
   "scenario": {
    "type": "string",
    "description": "the scenario's name, exactly as its `Scenario:` line reads"
   }
  },
  "required": [
   "feature",
   "scenario"
  ],
  "additionalProperties": false
 },
 "returns": {
  "form": "text",
  "text": "one line on standard output, `<feature>: scenario \\`<name>\\` @hash: <12 hex>`; exit status 0; the tag line written in place"
 },
 "failures": [
  {
   "code": "unreadable",
   "exit_status": 2,
   "condition": "the feature does not exist, or names no scenario matching <scenario>; one line on standard error beginning `unreadable:` names the feature, the scenario asked for, and the scenario names that do exist; nothing is written",
   "next": "give an existing feature path and one of the scenario names listed, then run again"
  },
  {
   "code": "unparseable",
   "exit_status": 1,
   "condition": "the feature has no gherkin block, the named scenario has no Given/When/Then text, or its tag line carries no `@hash:` to fill; one line on standard error beginning `unparseable:` names the feature and the scenario, and what is wrong with its text; nothing is written",
   "next": "repair the scenario's text or tag line and run again"
  },
  {
   "code": "usage",
   "exit_status": 2,
   "condition": "the arguments are not one of the six invocations this tool states \u2014 no path, a missing required flag, an unknown flag, or a flag without its value; one line on standard error beginning `usage:` names the invocations; nothing is read or written",
   "next": "run the invocation the use states, as written"
  },
  {
   "code": "unwritable",
   "exit_status": 1,
   "condition": "the feature could not be written; one line on standard error beginning `unwritable:` names the path and the reason",
   "next": "make the path writable, or give one that is, and run the invocation again"
  }
 ]
}

