input.command:
cp features/feat-run-measurement.md /tmp/frm-check.md && for s in "a session close records a cost row for each agent step" "a field the harness withholds is left blank" "minutes are recorded as wall-clock time"; do python3 basis/tools/artifact_tools.py fill-hash /tmp/frm-check.md --scenario "$s"; done; echo "--- diff of tool run vs file (empty means tags already matched):"; diff features/feat-run-measurement.md /tmp/frm-check.md && echo "no diff"; echo "--- independent recompute:"; python3 - <<'EOF'
import hashlib,re
txt=open('/home/vscode/rebaseline/features/feat-run-measurement.md').read()
block=txt.split('```gherkin')[1].split('```')[0]
cur=None;lines={}
for l in block.splitlines():
    s=l.strip()
    if s.startswith('Scenario:'):
        cur=s[len('Scenario:'):].strip(); lines[cur]=[s]
    elif cur and re.match(r'(Given|When|Then|And|But)\b',s):
        lines[cur].append(s)
tags=dict(re.findall(r'@hash:([0-9a-f]{12})\n\s*Scenario: (.*)',block))
tags={v:k for k,v in tags.items()}
for n,ls in lines.items():
    h=hashlib.sha256('\n'.join(ls).encode()).hexdigest()[:12]
    print(f"{'OK ' if tags.get(n)==h else 'MISMATCH'} {tags.get(n)} computed={h}  {n}")
EOF
